tor_q05_fenn_done","locale":"he","line_order":1,"content":"ויל יקבל את הפטיש שלו.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_done","locale":"he","line_order":2,"content":"הציירת תקבל את המברשת שלה.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_done","locale":"he","line_order":3,"content":"השומרים מצאו את הכריכים שלהם.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_done","locale":"he","line_order":4,"content":"ועכשיו אנחנו יודעים להשתמש ב my, your, his, her, our ו their.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_done","locale":"he","line_order":5,"content":"רגע... השומרים כבר אכלו את הכריכים.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_done","locale":"he","line_order":6,"content":"טוב, לפחות מצאנו אותם בזמן! כל הכבוד.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_done","locale":"he","line_order":7,"content":"קבלו 10 מטבעות.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_start","locale":"he","line_order":0,"content":"זה השלב האחרון של החיפוש.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_start","locale":"he","line_order":1,"content":"עכשיו נבדוק את כל הדברים שנמצאו בתוך התיבה.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_start","locale":"he","line_order":2,"content":"התחילו ליד שולחן הבחינה ובדקו את המשפט של המלך אליכם.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_start","locale":"he","line_order":3,"content":"אחר כך לכו לעגלה ואמרו בקול את אותו משפט.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_start","locale":"he","line_order":4,"content":"בנו שם גם את המשפט על הפטיש של ויל ועל המברשת של הציירת.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_start","locale":"he","line_order":5,"content":"אחר כך אמרו את משפט העדים ליד שולחן הבחינה.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_start","locale":"he","line_order":6,"content":"בסוף השלימו את המשפט של המלך על השומרים.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_start","locale":"he","line_order":7,"content":"אחרי כל הבדיקות חזרו אליי עם התשובה.","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
